describe('Element Manager - Add and Delete Elements', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/add_remove_elements/');
  });

  it('should add two elements and display two delete buttons, then delete one to leave one button', () => {
    // Verify initial state
    cy.get('[data-testid="content"]').should('be.visible');
    cy.get('[data-testid="elements"]').should('contain', '0 elements');

    // Click 'Add Element' button twice
    cy.get('[data-testid="Add Element"]').click();
    cy.get('[data-testid="elements"]').should('contain', '1 element');
    cy.get('[data-testid="Add Element"]').click();
    cy.get('[data-testid="elements"]').should('contain', '2 elements');

    // Verify two delete buttons are present
    cy.get('[data-testid="added-manually"]').should('have.length', 2);

    // Click first delete button
    cy.get('[data-testid="added-manually"]').first().click();

    // Verify only one delete button remains
    cy.get('[data-testid="added-manually"]').should('have.length', 1);

    // Verify list reflects deletion
    cy.get('[data-testid="elements"]').should('contain', '1 element');
  });

  it('should handle edge case where no elements are present and cannot delete', () => {
    // Verify initial state with no elements
    cy.get('[data-testid="content"]').should('be.visible');
    cy.get('[data-testid="elements"]').should('contain', '0 elements');

    // Click 'Add Element' button
    cy.get('[data-testid="Add Element"]').click();
    cy.get('[data-testid="elements"]').should('contain', '1 element');

    // Attempt to delete when no elements exist
    cy.get('[data-testid="added-manually"]').first().click();

    // Verify no error message and no delete button is shown
    cy.get('[data-testid="error-message"]').should('not.exist');
    cy.get('[data-testid="added-manually"]').should('not.exist');

    // Verify list still shows one element
    cy.get('[data-testid="elements"]').should('contain', '1 element');
  });
});
